#!/usr/bin/env bash
set -euo pipefail

V2_ROOT="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
REPO_ROOT="$(cd -- "$V2_ROOT/../../.." && pwd)"
BASELINE="$V2_ROOT/baseline/original-sha256.txt"

test -s "$BASELINE"
while IFS='  ' read -r expected path; do
  test -n "$path" || continue
  # Bundler caches are regenerated by an otherwise read-only local preview and
  # are recorded separately in the V2 report; they are not source artefacts.
  [[ "$path" == */node_modules/* ]] && continue
  actual="$(sha256sum "$REPO_ROOT/$path" | awk '{print $1}')"
  if [[ "$actual" != "$expected" ]]; then
    printf 'CAMBIO DETECTADO: %s\n' "$path" >&2
    exit 1
  fi
done < "$BASELINE"

printf 'Originales protegidos: hashes sin cambios.\n'
